What does this code print? Explain how each mutation determines the final values, including the value seen through `alias`.

```csharp
using System;

var original = new Box { Value = 10 };
var alias = original;

var a = new Snapshot { Count = 1, Shared = original };
var b = a;

b.Count = 2;
b.Shared.Value = 20;
b.Shared = new Box { Value = 30 };

Console.WriteLine(
    $"{a.Count}, {b.Count}, {a.Shared.Value}, {b.Shared.Value}, {alias.Value}");

public sealed class Box
{
    public int Value;
}

public struct Snapshot
{
    public int Count;
    public Box Shared;
}
